// Build script for the Nexus Sheet web UI (Phase 3.1).
//
// Bundles src/main.ts → dist/app.js with esbuild, then copies the static
// shell (index.html, style.css) and the WASM pkg (src/wasm/*) into dist/.
// The WASM pkg is generated by `pnpm build:wasm` (wasm-pack --target web);
// if it is missing, the app still loads but diff/merge features are disabled
// with a banner.
//
//   pnpm build           one-shot bundle + copy
//   pnpm dev             --watch --serve on http://localhost:5173
import * as esbuild from "esbuild";
import { cpSync, existsSync, mkdirSync } from "node:fs";

const watch = process.argv.includes("--watch");
const serve = process.argv.includes("--serve");

mkdirSync("dist", { recursive: true });
cpSync("index.html", "dist/index.html");
cpSync("style.css", "dist/style.css");

const wasmReady = existsSync("src/wasm/sync_engine_wasm.js");
if (wasmReady) {
  mkdirSync("dist/wasm", { recursive: true });
  cpSync("src/wasm/sync_engine_wasm.js", "dist/wasm/sync_engine_wasm.js");
  cpSync("src/wasm/sync_engine_wasm_bg.wasm", "dist/wasm/sync_engine_wasm_bg.wasm");
} else {
  console.warn(
    "⚠ src/wasm/ not found — run `pnpm build:wasm` first. " +
      "The UI will load but WASM diff/merge will be unavailable.",
  );
}

const ctx = await esbuild.context({
  entryPoints: ["src/main.ts"],
  bundle: true,
  format: "esm",
  target: "es2022",
  outfile: "dist/app.js",
  sourcemap: true,
  logLevel: "info",
});

if (watch) {
  await ctx.watch();
  console.log("watching for changes…");
} else {
  await ctx.rebuild();
  await ctx.dispose();
}

if (serve) {
  const server = await ctx.serve({ port: 5173, servedir: "dist" });
  console.log(`\n  ➜  dev server: http://localhost:${server.port}\n`);
}
